import sys

def solve():
    try:
        input_data = sys.stdin.read().strip()
        if not input_data:
            return
        n = int(input_data)
    except ValueError:
        return

    # Pre-generate all repdigit numbers between 100 and 999
    repdigits = []
    for d in range(1, 10):
        repdigits.append(d * 111)  # 111, 222, ..., 999

    # Find the smallest repdigit >= n
    for r in repdigits:
        if r >= n:
            print(r)
            return

if __name__ == "__main__":
    solve()
